import time as _time


class ExecutionHistory:
    """Record of all state transitions during an individual's execution in an environment.
    
    Stores observations, actions, rewards, errors, layer activations, termination
    flags, and timestamps for each step of an execution episode.
    """
    
    def __init__(self):
        # ``observations`` keeps the post-step observation returned by env.step()
        # for backward compatibility with existing metrics/processors.  The
        # optional ``pre_observations`` trace records the observation that the
        # controller actually perceived before taking each action, allowing
        # plots and verbose output to show the full transition.
        self.observations: List[np.ndarray] = []
        self.pre_observations: List[np.ndarray] = []
        self.actions: List[Any] = []
        self.rewards: List[float] = []
        self.errors: List[np.ndarray] = []
        self.layer_activations: Dict[str, List[np.ndarray]] = {}
        self.terminated: List[bool] = []
        self.truncated: List[bool] = []
        self.timestamps: List[float] = []
        self._start_time: Optional[float] = None
    
    def add_step(
        self,
        observation: np.ndarray,
        action: Any,
        reward: float,
        error: np.ndarray,
        done: bool = False,
        terminated: bool = False,
        truncated: bool = False,
        layer_activations: Optional[Dict[str, np.ndarray]] = None,
        pre_observation: Optional[np.ndarray] = None,
    ):
        """Record a single execution step.
        
        Args:
            observation: Environment observation returned after the action
            action: Action taken at this step
            reward: Reward received
            error: Comparator error values at this step
            done: Legacy flag (sets terminated=True if neither terminated/truncated given)
            terminated: Whether episode terminated at this step
            truncated: Whether episode was truncated at this step
            layer_activations: Optional dict mapping layer names to activation arrays
            pre_observation: Observation used to compute the action. If omitted,
                defaults to ``observation`` for compatibility with older callers.
        """
        if self._start_time is None:
            self._start_time = _time.time()
        
        self.observations.append(np.array(observation, dtype=np.float32))
        if pre_observation is None:
            pre_observation = observation
        self.pre_observations.append(np.array(pre_observation, dtype=np.float32))
        self.actions.append(action)
        self.rewards.append(float(reward))
        self.errors.append(np.array(error, dtype=np.float32))
        
        # Handle termination flags
        if not terminated and not truncated and done:
            terminated = True
        self.terminated.append(terminated)
        self.truncated.append(truncated)
        
        self.timestamps.append(_time.time() - self._start_time)
        
        if layer_activations is not None:
            for name, values in layer_activations.items():
                if name not in self.layer_activations:
                    self.layer_activations[name] = []
                self.layer_activations[name].append(np.array(values, dtype=np.float32))
    
    def __len__(self) -> int:
        return len(self.observations)
    
    @property
    def num_steps(self) -> int:
        """Number of recorded steps."""
        return len(self.observations)
    
    def get_observations_array(self) -> np.ndarray:
        """Return post-step observations as a 2D array (steps, obs_dim)."""
        if not self.observations:
            return np.array([])
        return np.stack(self.observations)

    def get_pre_observations_array(self) -> np.ndarray:
        """Return pre-action observations as a 2D array (steps, obs_dim)."""
        if not self.pre_observations:
            return np.array([])
        return np.stack(self.pre_observations)

    def get_complete_observations_array(self) -> np.ndarray:
        """Return the full state trajectory: initial observation plus post-step values."""
        post = self.get_observations_array()
        pre = self.get_pre_observations_array()
        if post.size == 0:
            return post
        if pre.size == 0:
            return post
        return np.concatenate([pre[:1], post], axis=0)
    
    def get_actions_array(self) -> np.ndarray:
        """Return actions as an array."""
        if not self.actions:
            return np.array([])
        return np.array(self.actions)
    
    def get_rewards_array(self) -> np.ndarray:
        """Return rewards as a 1D array."""
        return np.array(self.rewards, dtype=np.float32)
    
    def get_errors_array(self) -> np.ndarray:
        """Return errors as a 2D array (steps, error_dim)."""
        if not self.errors:
            return np.array([])
        return np.stack(self.errors)
    
    def get_layer_activations_array(self, layer_name: str) -> np.ndarray:
        """Return activations for a specific layer as a 2D array (steps, units)."""
        if layer_name not in self.layer_activations:
            raise ValueError(f"Layer '{layer_name}' not found in history. Available: {list(self.layer_activations.keys())}")
        return np.stack(self.layer_activations[layer_name])
    
    def get_error_levels(self) -> Dict[str, np.ndarray]:
        """Extract per-level error arrays from the concatenated error signal.
        
        Returns dict mapping level names (e.g. 'CL00', 'CL01') to arrays
        of shape (steps, units_at_level). Requires layer_activations to
        contain comparator layer data, otherwise splits error array evenly.
        """
        # If we have comparator layer activations, use those directly
        cl_layers = {k: v for k, v in self.layer_activations.items() if k.startswith('CL')}
        if cl_layers:
            return {k: np.stack(v) for k, v in sorted(cl_layers.items())}
        
        # Fallback: return the full error array as a single level
        errors = self.get_errors_array()
        if errors.size == 0:
            return {}
        return {'errors': errors}


