# Mapping of legacy environment names to their current Gymnasium equivalents.
_LEGACY_ENV_NAME_FIXES: Dict[str, str] = {
    "LunarLanderContinuous-v2": "LunarLanderContinuous-v3",
}


def _current_smooth_factors_from_model(self) -> Dict[str, Any]:
    """Return smooth_factors reflecting current trainable smooth-layer weights.

    ``self.smooth_factors`` records constructor values.  During evolution the
    Keras ``*_smooth`` layer weights are what actually mutate, so saved configs
    and Comet assets should report those current values in
    ``hierarchy.smooth_factors``.
    """
    factors = _to_serializable(getattr(self, "smooth_factors", None))
    if not isinstance(factors, dict) or self.model is None:
        return factors

    factors = {
        "perception": list(factors.get("perception", [])),
        "reference": list(factors.get("reference", [])),
        "output": list(factors.get("output", [])),
        "actions": factors.get("actions", 0.5),
    }
    role_prefixes = {"perception": "PL", "reference": "RL", "output": "OL"}
    activation_funcs = getattr(self, "activation_funcs", {})

    for role, prefix in role_prefixes.items():
        role_activations = activation_funcs.get(role, []) if isinstance(activation_funcs, dict) else []
        for level_idx in range(len(getattr(self, "levels", []) or [])):
            if level_idx >= len(role_activations) or role_activations[level_idx] != "smooth":
                continue
            layer_name = f"{prefix}{level_idx:02d}_smooth"
            try:
                layer = self.model.get_layer(layer_name)
                weights = layer.get_weights()
            except Exception:
                continue
            if weights:
                while len(factors[role]) <= level_idx:
                    factors[role].append(0.5)
                factors[role][level_idx] = _to_serializable(weights[0])

    if isinstance(activation_funcs, dict) and activation_funcs.get("actions") == "smooth":
        try:
            layer = self.model.get_layer("Actions_smooth")
            weights = layer.get_weights()
        except Exception:
            weights = []
        if weights:
            factors["actions"] = _to_serializable(weights[0])

    return factors


def _config_impl(self) -> Dict[str, Any]:
    """Return complete configuration dictionary."""
    if self.model is None:
        raise RuntimeError("Individual must be compiled before exporting config")

    self._store_weights()

    weights = {}
    biases = {}
    layer_parameters = {}
    for layer in self.model.layers:
        layer_weights = layer.get_weights()
        if len(layer_weights) > 0:
            weights[layer.name] = _to_serializable(layer_weights[0])
        if getattr(layer, "bias", None) is not None and len(layer_weights) > 1:
            biases[layer.name] = _to_serializable(layer_weights[1])
        if hasattr(layer, "range_val") and hasattr(layer, "slope"):
            layer_parameters[layer.name] = {
                "range_val": _to_serializable(layer_weights[0]),
                "slope": _to_serializable(layer_weights[1]),
            }

    config = {
        "env_name": self.env_name,
        "env_properties": _to_serializable(self.env_properties),
        "hierarchy": {
            "levels": list(self.levels),
            "activation_funcs": _to_serializable(self.activation_funcs),
            "smooth_factors": _current_smooth_factors_from_model(self),
            "weight_types": _to_serializable(self.weight_types),
            "obs_connection_level": int(self.obs_connection_level),
            "top_reference_weight_init": getattr(self, "top_reference_weight_init", "ones"),
            "reference_values": _to_serializable(getattr(self, "reference_values", [])),
            "evolve_references": bool(getattr(self, "evolve_references", False)),
            "top_level_obs_indices": _to_serializable(getattr(self, "top_level_obs_indices", None)),
            "zerolevel_inputs_indexes": _to_serializable(getattr(self, "zerolevel_inputs_indexes", None)),
        },
        "weights": weights,
        "biases": biases,
        "layer_parameters": layer_parameters,
        "fixed_weights": sorted(list(getattr(self, "fixed_weights", set()))),
        "fixed_levels": sorted(list(getattr(self, "fixed_levels", set()))),
        "metadata": {
            "created": datetime.now(timezone.utc).isoformat(),
            "fitness": _to_serializable(self.fitness),
            "fitness_method": _to_serializable(getattr(self, "fitness_method", None)),
            "fitness_source": _to_serializable(getattr(self, "fitness_source", None)),
            "fitness_observation_indices": _to_serializable(getattr(self, "fitness_observation_indices", None)),
            "fitness_targets": _to_serializable(getattr(self, "fitness_targets", None)),
            "run_steps": _to_serializable(getattr(self, "run_steps", 0)),
            "total_reward": _to_serializable(getattr(self, "total_reward", 0.0)),
            "last_reward": _to_serializable(getattr(self, "last_reward", None)),
            "success": _to_serializable(getattr(self, "success", False)),
            "random_seed": _to_serializable(self.random_seed),
        },
    }

    return config




