def _save_config_impl(self, filepath: str, format: str = "json") -> None:
    """Save configuration to JSON or pickle file."""
    config = self.config()
    file_path = Path(filepath)
    file_path.parent.mkdir(parents=True, exist_ok=True)

    fmt = format.lower()
    if fmt == "json":
        with open(file_path, "w", encoding="utf-8") as f:
            json.dump(config, f, indent=2)
    elif fmt in {"pickle", "pkl"}:
        with open(file_path, "wb") as f:
            pickle.dump(config, f)
    else:
        raise ValueError(f"Unknown format '{format}'. Use 'json' or 'pickle'.")


def _load_config_impl(cls, filepath: str) -> Dict[str, Any]:
    """Load configuration dictionary from JSON or pickle file."""
    file_path = Path(filepath)
    suffix = file_path.suffix.lower()
    if suffix in {".pkl", ".pickle"}:
        with open(file_path, "rb") as f:
            return pickle.load(f)

    with open(file_path, "r", encoding="utf-8") as f:
        return json.load(f)



