def _infer_smooth_factors_from_saved_weights(
    hierarchy: Dict[str, Any], weights: Dict[str, Any]
) -> Optional[Dict[str, Any]]:
    """Infer per-layer smooth factors for configs saved before they were explicit.

    Older ``--save-config`` output stored trainable ``*_smooth`` layer weights but
    did not store ``hierarchy.smooth_factors``.  Reconstructing such a config with
    default scalar smooth factors builds scalar ``smooth_factor`` variables, while
    the saved weights may be vectors (for example ``[0.1, 0.2]`` for a 2-unit
    layer).  Passing the saved values back as constructor smooth factors recreates
    the original variable shapes before ``set_weights`` runs.
    """
    activation_funcs = hierarchy.get("activation_funcs", "linear")
    levels = hierarchy.get("levels", [])
    if not isinstance(activation_funcs, dict) or not levels:
        return None

    inferred: Dict[str, Any] = {
        "perception": [0.5] * len(levels),
        "reference": [0.5] * len(levels),
        "output": [0.5] * len(levels),
        "actions": 0.5,
    }
    found = False
    role_prefixes = {
        "perception": "PL",
        "reference": "RL",
        "output": "OL",
    }

    for role, prefix in role_prefixes.items():
        role_activations = activation_funcs.get(role, [])
        for level_idx in range(len(levels)):
            if level_idx >= len(role_activations) or role_activations[level_idx] != "smooth":
                continue
            layer_name = f"{prefix}{level_idx:02d}_smooth"
            if layer_name in weights:
                inferred[role][level_idx] = weights[layer_name]
                found = True

    if activation_funcs.get("actions") == "smooth" and "Actions_smooth" in weights:
        action_value = weights["Actions_smooth"]
        if isinstance(action_value, list):
            inferred["actions"] = float(action_value[0]) if action_value else 0.5
        else:
            inferred["actions"] = float(action_value)
        found = True

    return inferred if found else None


def _from_config_impl(cls, config: Dict[str, Any]) -> "DHPCTIndividual":
    """Create a compiled individual from a configuration dictionary."""
    if "env_name" not in config or "hierarchy" not in config:
        raise KeyError("Config must include 'env_name' and 'hierarchy'")

    hierarchy = config["hierarchy"]
    weights = config.get("weights", {})
    smooth_factors = hierarchy.get("smooth_factors", None)
    if smooth_factors is None:
        smooth_factors = _infer_smooth_factors_from_saved_weights(hierarchy, weights)

    individual = cls(
        env_name=config["env_name"],
        levels=hierarchy["levels"],
        activation_funcs=hierarchy.get("activation_funcs", "linear"),
        weight_types=hierarchy.get("weight_types", "float"),
        fixed_weights=set(config.get("fixed_weights", [])),
        fixed_levels=set(config.get("fixed_levels", [])),
        obs_connection_level=hierarchy.get("obs_connection_level", 0),
        random_seed=config.get("metadata", {}).get("random_seed", None),
        smooth_factors=smooth_factors,
        reference_values=hierarchy.get("reference_values", None),
        evolve_references=hierarchy.get("evolve_references", False),
        top_reference_weight_init=hierarchy.get("top_reference_weight_init", "ones"),
        top_level_obs_indices=hierarchy.get("top_level_obs_indices", None),
        zerolevel_inputs_indexes=hierarchy.get("zerolevel_inputs_indexes", None),
    )
    individual.compile()

    weights = config.get("weights", {})
    biases = config.get("biases", {})
    layer_parameters = config.get("layer_parameters", {})

    for layer in individual.model.layers:
        current = layer.get_weights()
        if len(current) == 0:
            continue

        layer_name = layer.name
        if layer_name not in weights and layer_name not in biases and layer_name not in layer_parameters:
            continue

        if layer_name in layer_parameters and hasattr(layer, "range_val") and hasattr(layer, "slope"):
            params = layer_parameters[layer_name]
            try:
                layer.set_weights([
                    _to_numpy(params.get("range_val", current[0])),
                    _to_numpy(params.get("slope", current[1])),
                ])
            except Exception as exc:
                raise ValueError(f"Failed to restore parameters for layer '{layer_name}': {exc}")
            continue

        new_weights = []
        kernel = _to_numpy(weights[layer_name]) if layer_name in weights else current[0]
        if layer_name == f"RL{len(individual.levels) - 1:02d}":
            # Top-level reference gains are invariant. Ignore evolved/restored
            # values from older configs and keep ReferencesInput pass-through.
            kernel = np.ones_like(current[0], dtype=current[0].dtype)
        elif (
            layer_name == f"PL{len(individual.levels) - 1:02d}"
            and getattr(individual, "top_level_obs_indices", None) is not None
        ):
            # Direct top-level observation perceptions are fixed identity mappings.
            # Ignore older saved/evolved gains (including legacy ElementWise vectors)
            # so top-level comparator error is measured against the raw selected obs.
            kernel = np.eye(
                np.asarray(current[0]).shape[0],
                np.asarray(current[0]).shape[1],
                dtype=current[0].dtype,
            )
        elif (
            layer_name.endswith("_smooth")
            and np.asarray(kernel).shape == ()
            and np.asarray(current[0]).shape != ()
        ):
            # Backward compatibility: older configs may contain a scalar
            # smooth_factor for a whole ExponentialSmoothLayer. Newer models use
            # one smooth_factor per output unit, so broadcast old scalar values
            # to the layer's current vector shape before set_weights().
            kernel = np.full_like(current[0], float(kernel), dtype=current[0].dtype)
        elif (
            layer_name == "PL00"
            and np.asarray(kernel).ndim == 2
            and np.asarray(current[0]).ndim == 2
            and np.asarray(kernel).shape != np.asarray(current[0]).shape
            and np.asarray(kernel).shape[1] == np.asarray(current[0]).shape[1]
        ):
            # Backward compatibility for configs saved before
            # top_level_obs_indices dimensions were excluded from PL00.  Old
            # PL00 kernels may still have rows for the full observation vector;
            # select only the rows that feed the current effective level-0 input.
            effective_indices = getattr(individual, "level0_observation_indices", None)
            if effective_indices is not None:
                original_indices = hierarchy.get("zerolevel_inputs_indexes", None)
                if original_indices is None:
                    obs_shape = individual.env_properties.get("observation_shape", (0,))
                    obs_dim = int(obs_shape[0]) if len(obs_shape) > 0 else np.asarray(kernel).shape[0]
                    original_indices = list(range(obs_dim))
                original_indices = [int(idx) for idx in original_indices]
                row_positions = [
                    original_indices.index(int(idx))
                    for idx in effective_indices
                    if int(idx) in original_indices
                ]
                if len(row_positions) == np.asarray(current[0]).shape[0]:
                    kernel = np.asarray(kernel)[row_positions, :]
        new_weights.append(kernel)

        if len(current) > 1:
            bias = _to_numpy(biases[layer_name]) if layer_name in biases else current[1]
            new_weights.append(bias)

        try:
            layer.set_weights(new_weights)
        except Exception as exc:
            raise ValueError(f"Failed to restore weights for layer '{layer_name}': {exc}")

    individual._store_weights()
    individual.fitness = config.get("metadata", {}).get("fitness", None)
    individual.fitness_method = config.get("metadata", {}).get("fitness_method", None)
    individual.fitness_source = config.get("metadata", {}).get("fitness_source", None)
    individual.fitness_observation_indices = config.get("metadata", {}).get("fitness_observation_indices", None)
    individual.fitness_targets = config.get("metadata", {}).get("fitness_targets", None)
    individual.run_steps = config.get("metadata", {}).get("run_steps", 0)
    individual.total_reward = config.get("metadata", {}).get("total_reward", 0.0)
    individual.last_reward = config.get("metadata", {}).get("last_reward", None)
    individual.success = bool(config.get("metadata", {}).get("success", False))
    return individual



