def _pct_func_config(
    func_type: str,
    name: str,
    value: float = 0.0,
    links: Optional[List[str]] = None,
    **extra,
 ):
    links_dict = {str(i): link for i, link in enumerate(links or [])}
    payload = {"type": func_type, "name": name, "value": float(value), "links": links_dict}
    for key, val in extra.items():
        payload[key] = _to_serializable(val)
    return payload


def _looks_like_pct_hierarchy_config(config: Dict[str, Any]) -> bool:
    return (
        isinstance(config, dict)
        and config.get("type") in {"PCTHierarchy", "Individual"}
        and "name" in config
        and isinstance(config.get("levels"), dict)
        and "pre" in config
        and "post" in config
    )


def _extract_env_name_from_legacy(config: Dict[str, Any]) -> str:
    env_name = config.get("env_name")
    if isinstance(env_name, str) and env_name:
        return env_name

    pre = config.get("pre", {})
    if isinstance(pre, dict):
        for item in pre.values():
            if isinstance(item, dict):
                candidate = item.get("env_name")
                if isinstance(candidate, str) and candidate:
                    return candidate

    return "CartPole-v1"


def _is_weighted_sum_type(func_type: Any) -> bool:
    return isinstance(func_type, str) and func_type.endswith("WeightedSum")


# %% ../nbs/02_individual_utils.ipynb #0727f4ca
def _legacy_env_type(env_name: str) -> str:
    """Return the legacy pct environment class-style name for a Gymnasium id."""
    if not env_name:
        return "Environment"
    return "".join(part[:1].upper() + part[1:] for part in str(env_name).replace("-", "_").split("_") if part)


def _legacy_smooth_factor_for_slot(smooth_factors: Dict[str, Any], role: str, lvl: int, col: Optional[int] = None) -> float:
    value = smooth_factors.get(role, 0.5)
    if role != "actions" and isinstance(value, list):
        value = value[lvl] if lvl < len(value) else 0.5
    if col is not None and isinstance(value, (list, tuple, np.ndarray)):
        return float(value[col]) if col < len(value) else 0.5
    if isinstance(value, (list, tuple, np.ndarray)):
        return float(value[0]) if len(value) else 0.5
    return float(value)


def _legacy_weight_list(weights: Dict[str, Any], layer_name: str, col: int, length: int, default: float = 1.0) -> List[float]:
    arr = np.array(weights.get(layer_name, []), dtype=np.float32)
    if arr.size == 0:
        return [float(default)] * int(length)
    if arr.ndim == 0:
        return [float(arr)] * int(length)
    if arr.ndim == 1:
        if int(length) == 1 and col < arr.shape[0]:
            return [float(arr[col])]
        vals = arr[: int(length)]
        if vals.shape[0] < int(length):
            vals = np.pad(vals, (0, int(length) - vals.shape[0]), constant_values=default)
        return vals.astype(float).tolist()
    if arr.ndim >= 2:
        if arr.shape[1] > col:
            vals = arr[: int(length), col]
        else:
            vals = np.full(int(length), float(default), dtype=np.float32)
        if vals.shape[0] < int(length):
            vals = np.pad(vals, (0, int(length) - vals.shape[0]), constant_values=default)
        return vals.astype(float).tolist()
    return [float(default)] * int(length)


def _legacy_gain(weights: Dict[str, Any], layer_name: str, col: int, default: float = 1.0) -> float:
    arr = np.array(weights.get(layer_name, []), dtype=np.float32)
    if arr.size == 0:
        return float(default)
    if arr.ndim == 0:
        return float(arr)
    if arr.ndim == 1:
        return float(arr[col]) if col < arr.shape[0] else float(default)
    if arr.ndim >= 2:
        return float(arr[0, col]) if arr.shape[1] > col else float(default)
    return float(default)


def _legacy_weighted_function_config(
    activation: str,
    name: str,
    links: List[str],
    weights: List[float],
    smooth_factor: float = 0.5,
    value: float = 0.0,
) -> Dict[str, Any]:
    """Build the closest legacy pct weighted-function config for a DPCT activation."""
    if activation == "smooth":
        return _pct_func_config(
            "EASmoothWeightedSum",
            name,
            value=value,
            links=links,
            weights=weights,
            smooth_factor=smooth_factor,
        )
    if activation == "sigmoid":
        return _pct_func_config(
            "EASigmoidWeightedSum",
            name,
            value=value,
            links=links,
            weights=weights,
        )
    return _pct_func_config("EAWeightedSum", name, value=value, links=links, weights=weights)


def config_to_legacy_config(
    config: Dict[str, Any],
    *,
    name: Optional[str] = None,
    env_inputs_names: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """Convert a saved ``DHPCTIndividual.config()`` dictionary to legacy pct config.

    The returned dictionary follows the ``PCTHierarchy.get_config()`` structure
    used by the legacy ``pct`` library, including environment ``pre`` nodes,
    hierarchical ``PCTNode`` levels, and action ``post`` nodes.  It is intended
    for ``pct.hierarchy.PCTHierarchy.from_config(...)`` or for embedding as the
    ``config = {...}`` payload in old ``.properties`` files.

    Args:
        config: A dictionary returned by ``DHPCTIndividual.config()`` or loaded
            from a saved DPCT JSON file.
        name: Optional legacy hierarchy name.  Defaults to ``dpct_<env_name>``.
        env_inputs_names: Optional display names for observation inputs.  When
            omitted, names are generated as ``I0``, ``I1``, ... from observation
            indices.

    Returns:
        Legacy pct hierarchy configuration dictionary.
    """
    if not isinstance(config, dict) or "hierarchy" not in config:
        raise ValueError("config must be a DHPCTIndividual.config() dictionary")

    hierarchy = config.get("hierarchy", {})
    levels = [int(x) for x in hierarchy.get("levels", [])]
    if not levels:
        raise ValueError("config['hierarchy']['levels'] must contain at least one level")

    env_name = str(config.get("env_name", "CartPole-v1"))
    env_type = _legacy_env_type(env_name)
    env_props = config.get("env_properties", {}) or {}
    obs_shape = env_props.get("observation_shape") or env_props.get("observation_space_shape") or []
    action_shape = env_props.get("action_shape") or []
    obs_dim = int(obs_shape[0]) if len(obs_shape) > 0 else 0
    action_dim = int(action_shape[0]) if len(action_shape) > 0 else 1

    activation_funcs = hierarchy.get("activation_funcs", {}) or {}
    smooth_factors = hierarchy.get("smooth_factors", {}) or {}
    weights = config.get("weights", {}) or {}
    reference_values = np.array(hierarchy.get("reference_values", []), dtype=np.float32).reshape(-1)
    top_obs = hierarchy.get("top_level_obs_indices")
    zero_inputs = hierarchy.get("zerolevel_inputs_indexes")

    if obs_dim <= 0:
        pl00 = np.array(weights.get("PL00", []), dtype=np.float32)
        obs_dim = int(pl00.shape[0]) if pl00.ndim >= 2 else int(levels[0])

    if top_obs is not None:
        top_obs = [int(idx) for idx in top_obs]
        level0_indices = [int(idx) for idx in (zero_inputs if zero_inputs is not None else range(obs_dim)) if int(idx) not in set(top_obs)]
    else:
        level0_indices = [int(idx) for idx in (zero_inputs if zero_inputs is not None else range(obs_dim))]

    all_input_indices = []
    for idx in list(level0_indices) + (list(top_obs) if top_obs is not None else []):
        if idx not in all_input_indices:
            all_input_indices.append(idx)
    if not all_input_indices:
        all_input_indices = list(range(obs_dim))

    if env_inputs_names is None:
        input_names = {idx: f"I{idx}" for idx in all_input_indices}
    else:
        if len(env_inputs_names) != len(all_input_indices):
            raise ValueError("env_inputs_names length must match the number of used observation indices")
        input_names = {idx: str(label) for idx, label in zip(all_input_indices, env_inputs_names)}

    pre = {
        "pre0": {
            "type": env_type,
            "name": env_type,
            "value": [0.0] * (obs_dim + action_dim),
            "links": {str(i): f"Action{i + 1}" for i in range(action_dim)},
            "env_name": env_name,
            "reward": 0,
            "done": False,
            "info": {},
        }
    }
    for pre_idx, obs_idx in enumerate(all_input_indices, start=1):
        pre[f"pre{pre_idx}"] = {
            "type": "IndexedParameter",
            "name": input_names[obs_idx],
            "value": 0.0,
            "links": {"0": env_type},
            "index": int(obs_idx),
        }

    pct_levels: Dict[str, Any] = {}
    for lvl, units in enumerate(levels):
        nodes: Dict[str, Any] = {}
        for col in range(int(units)):
            per_name = f"PL{lvl:02d}C{col:02d}"
            ref_name = f"RL{lvl:02d}C{col:02d}"
            com_name = f"CL{lvl:02d}C{col:02d}"
            out_name = f"OL{lvl:02d}C{col:02d}"

            per_activation = activation_funcs.get("perception", ["linear"] * len(levels))[lvl]
            ref_activation = activation_funcs.get("reference", ["linear"] * len(levels))[lvl]
            out_activation = activation_funcs.get("output", ["linear"] * len(levels))[lvl]

            if lvl == 0:
                per_links = [input_names[idx] for idx in level0_indices]
                per_weights = _legacy_weight_list(weights, f"PL{lvl:02d}", col, len(per_links), default=1.0)
            elif lvl == len(levels) - 1 and top_obs is not None:
                obs_idx = top_obs[col]
                per_links = [input_names[obs_idx]]
                per_weights = [1.0]
            else:
                per_links = [f"PL{lvl - 1:02d}C{i:02d}" for i in range(int(levels[lvl - 1]))]
                per_weights = _legacy_weight_list(weights, f"PL{lvl:02d}", col, len(per_links), default=1.0)
            per_cfg = _legacy_weighted_function_config(
                per_activation,
                per_name,
                per_links,
                per_weights,
                _legacy_smooth_factor_for_slot(smooth_factors, "perception", lvl, col),
            )

            if lvl == len(levels) - 1:
                ref_value = float(reference_values[col]) if col < reference_values.shape[0] else 0.0
                ref_cfg = _pct_func_config("EAConstant", ref_name, value=ref_value, links=[])
            else:
                ref_links = [f"OL{lvl + 1:02d}C{i:02d}" for i in range(int(levels[lvl + 1]))]
                ref_weights = _legacy_weight_list(weights, f"RL{lvl:02d}", col, len(ref_links), default=1.0)
                ref_cfg = _legacy_weighted_function_config(
                    ref_activation,
                    ref_name,
                    ref_links,
                    ref_weights,
                    _legacy_smooth_factor_for_slot(smooth_factors, "reference", lvl, col),
                )

            com_cfg = _pct_func_config("Subtract", com_name, value=0.0, links=[ref_name, per_name])
            gain = _legacy_gain(weights, f"OL{lvl:02d}", col, default=1.0)
            if out_activation == "smooth":
                out_cfg = _legacy_weighted_function_config(
                    out_activation,
                    out_name,
                    [com_name],
                    [gain],
                    _legacy_smooth_factor_for_slot(smooth_factors, "output", lvl, col),
                )
            elif out_activation == "sigmoid":
                out_cfg = _legacy_weighted_function_config(out_activation, out_name, [com_name], [gain])
            else:
                out_cfg = _pct_func_config("EAProportional", out_name, value=0.0, links=[com_name], gain=gain)

            node_cfg = {
                "type": "PCTNode",
                "name": f"L{lvl}C{col}",
                "refcoll": {"0": ref_cfg},
                "percoll": {"0": per_cfg},
                "comcoll": {"0": com_cfg},
                "outcoll": {"0": out_cfg},
            }
            nodes[f"col{col}"] = {"col": col, "node": node_cfg}
        pct_levels[f"level{lvl}"] = {"level": lvl, "nodes": nodes}

    action_activation = activation_funcs.get("actions", "linear")
    post: Dict[str, Any] = {}
    action_links = [f"OL00C{i:02d}" for i in range(int(levels[0]))]
    action_weights = np.array(weights.get("Actions", []), dtype=np.float32)
    for action_idx in range(action_dim):
        if action_weights.ndim >= 2 and action_weights.shape[1] > action_idx:
            aw = action_weights[: int(levels[0]), action_idx].astype(float).tolist()
        elif action_weights.ndim == 1 and action_dim == 1:
            aw = action_weights[: int(levels[0])].astype(float).tolist()
        else:
            aw = [1.0] * int(levels[0])
        post_name = f"Action{action_idx + 1}"
        if action_activation == "smooth":
            post_cfg = _legacy_weighted_function_config(
                action_activation,
                post_name,
                action_links,
                aw,
                _legacy_smooth_factor_for_slot(smooth_factors, "actions", 0, action_idx),
            )
        elif action_activation == "sigmoid":
            post_cfg = _legacy_weighted_function_config(action_activation, post_name, action_links, aw)
        else:
            post_cfg = _pct_func_config("EAWeightedSum", post_name, value=0.0, links=action_links, weights=aw)
        post[f"post{action_idx}"] = post_cfg

    return {
        "type": "PCTHierarchy",
        "name": name or f"dpct_{env_name}",
        "pre": pre,
        "levels": pct_levels,
        "post": post,
    }


def _to_legacy_config_impl(self) -> Dict[str, Any]:
    """Convert this individual to legacy pct ``PCTHierarchy.get_config()`` format."""
    return config_to_legacy_config(self.config())


# %% ../nbs/02_individual_utils.ipynb #c82f8c4f
def _extract_pct_levels(config: Dict[str, Any]) -> List[int]:
    levels_dict = config["levels"]
    ordered = sorted(levels_dict.values(), key=lambda item: int(item.get("level", 0)))
    return [len(level_info.get("nodes", {})) for level_info in ordered]


def _safe_node_get(config: Dict[str, Any], lvl: int, col: int) -> Dict[str, Any]:
    return config["levels"][f"level{lvl}"]["nodes"][f"col{col}"]["node"]


# %% ../nbs/02_individual_utils.ipynb #d5ac8288
def _legacy_func_cfg(config: Dict[str, Any], lvl: int, col: int, coll_name: str) -> Dict[str, Any]:
    """Return one legacy node function config, or an empty dict when absent."""
    node_cfg = _safe_node_get(config, lvl, col)
    return node_cfg.get(coll_name, {}).get("0", {})


def _legacy_func_activation(func_cfg: Dict[str, Any]) -> str:
    """Map legacy PCT function type to the closest DPCT activation name."""
    func_type = func_cfg.get("type", "") or ""
    if "Sigmoid" in func_type:
        return "sigmoid"
    if "SmoothWeightedSum" in func_type:
        return "smooth"
    return "linear"


def _legacy_func_smooth_factor(func_cfg: Dict[str, Any]) -> float:
    """Extract a legacy smooth factor, defaulting to DPCT's smooth default."""
    if _legacy_func_activation(func_cfg) != "smooth":
        return 0.5
    return float(func_cfg.get("smooth_factor", 0.5))


def _extract_legacy_activation_and_smooth(
    legacy_config: Dict[str, Any], levels: List[int]
) -> tuple[Dict[str, Any], Dict[str, Any]]:
    """Infer DPCT activation/smooth-factor settings from legacy PCT nodes.

    DPCT smooth layers support either scalar or per-unit smooth factors, so
    legacy EASmoothWeightedSum columns keep their individual smooth factors
    instead of being silently downgraded to plain linear layers.
    """
    role_to_coll = {
        "perception": "percoll",
        "reference": "refcoll",
        "output": "outcoll",
    }
    activation_funcs = {
        "perception": [],
        "reference": [],
        "output": [],
        "actions": "linear",
    }
    smooth_factors = {
        "perception": [],
        "reference": [],
        "output": [],
        "actions": 0.5,
    }

    for lvl, units in enumerate(levels):
        # Use the first node with a config for each role; all current DPCT layers
        # are level-wide, not per-column.
        for role, coll_name in role_to_coll.items():
            selected = {}
            selected_factors = []
            for col in range(units):
                candidate = _legacy_func_cfg(legacy_config, lvl, col, coll_name)
                if candidate and not selected:
                    selected = candidate
                selected_factors.append(_legacy_func_smooth_factor(candidate))
            activation = _legacy_func_activation(selected)
            activation_funcs[role].append(activation)
            if activation == "smooth":
                smooth_factors[role].append(selected_factors)
            else:
                smooth_factors[role].append(0.5)

    post = legacy_config.get("post", {})
    first_post = next((post[key] for key in sorted(post)), {}) if post else {}
    activation_funcs["actions"] = _legacy_func_activation(first_post)
    smooth_factors["actions"] = _legacy_func_smooth_factor(first_post)
    return activation_funcs, smooth_factors


def _legacy_weight_for_link(func_cfg: Dict[str, Any], link_name: str, default: float = 1.0) -> float:
    """Return the legacy weight corresponding to a named link."""
    links = func_cfg.get("links", {}) or {}
    weights = func_cfg.get("weights", None)
    if weights is None:
        return default
    for link_idx, link_key in enumerate(sorted(links, key=lambda k: int(k))):
        if links[link_key] == link_name and link_idx < len(weights):
            return float(weights[link_idx])
    return default


def _legacy_first_weight(func_cfg: Dict[str, Any], default: float = 1.0) -> float:
    weights = func_cfg.get("weights", None)
    if weights is None or len(weights) == 0:
        return default
    return float(weights[0])


def _legacy_output_weight(func_cfg: Dict[str, Any], default: float = 1.0) -> float:
    """Extract a legacy output gain from Proportional or WeightedSum configs."""
    if func_cfg.get("gain") is not None:
        return float(func_cfg["gain"])
    return _legacy_first_weight(func_cfg, default=default)


def _from_pct_legacy_config_impl(cls, legacy_config: Dict[str, Any]) -> "DHPCTIndividual":
    levels = _extract_pct_levels(legacy_config)
    env_name = _extract_env_name_from_legacy(legacy_config)

    # Patch deprecated Gymnasium environment names
    env_name = _LEGACY_ENV_NAME_FIXES.get(env_name, env_name)

    activation_funcs, smooth_factors = _extract_legacy_activation_and_smooth(
        legacy_config, levels
    )

    reference_values = legacy_config.get("references")
    if reference_values is None:
        top_level = len(levels) - 1
        reference_values = []
        for col in range(levels[-1]):
            ref_cfg = _legacy_func_cfg(legacy_config, top_level, col, "refcoll")
            if ref_cfg.get("value") is not None and not _is_weighted_sum_type(ref_cfg.get("type")):
                reference_values.append(float(ref_cfg["value"]))
            else:
                reference_values.append(0.0)

    individual = cls(
        env_name=env_name,
        levels=levels,
        activation_funcs=activation_funcs,
        smooth_factors=smooth_factors,
        weight_types="float",
        random_seed=None,
        reference_values=reference_values,
        top_level_obs_indices=legacy_config.get("toplevel_inputs_indexes"),
        zerolevel_inputs_indexes=legacy_config.get("zerolevel_inputs_indexes"),
    )
    individual.compile()

    for lvl, units in enumerate(levels):
        # Transfer perception weights.
        pl_layer = individual.model.get_layer(f"PL{lvl:02d}")
        pl_current = pl_layer.get_weights()
        if lvl == len(levels) - 1 and getattr(individual, "top_level_obs_indices", None) is not None:
            # Current direct top-level observation perception is fixed identity.
            # Do not import legacy/evolved perception gains or smooth state for this path.
            pass
        elif len(pl_current) > 0 and pl_current[0].ndim == 1:
            # ElementWiseMultiplyLayer — one-to-one gathered observation mapping.
            per_weights_1d = np.ones(units, dtype=np.float32)
            for col in range(units):
                per_cfg = _legacy_func_cfg(legacy_config, lvl, col, "percoll")
                if _is_weighted_sum_type(per_cfg.get("type")):
                    per_weights_1d[col] = _legacy_first_weight(per_cfg)
            pl_layer.set_weights([per_weights_1d])
        elif lvl == 0:
            # Level-0 Dense sees either the full observation vector or the gathered
            # zerolevel subset.  Legacy weights are positional over their links, so
            # build the actual Dense input kernel directly rather than writing into
            # absolute observation rows and gathering afterward.
            if getattr(individual, "zerolevel_inputs_indexes", None) is not None:
                input_dim = len(individual.zerolevel_inputs_indexes)
            else:
                obs_shape = individual.env_properties.get("observation_shape", (0,))
                input_dim = int(obs_shape[0]) if len(obs_shape) > 0 else 0
            per_kernel = np.zeros((input_dim, units), dtype=np.float32)
            for col in range(units):
                per_cfg = _legacy_func_cfg(legacy_config, lvl, col, "percoll")
                if _is_weighted_sum_type(per_cfg.get("type")):
                    weights = np.array(per_cfg.get("weights", [1.0] * input_dim), dtype=np.float32).reshape(-1)
                    limit = min(input_dim, weights.shape[0])
                    per_kernel[:limit, col] = weights[:limit]
            if len(pl_current) > 0:
                new_weights = [per_kernel]
                if len(pl_current) > 1:
                    new_weights.append(np.array(pl_current[1], dtype=np.float32))
                pl_layer.set_weights(new_weights)
        else:
            prev_units = levels[lvl - 1]
            per_kernel = np.zeros((prev_units, units), dtype=np.float32)
            for col in range(units):
                per_cfg = _legacy_func_cfg(legacy_config, lvl, col, "percoll")
                if _is_weighted_sum_type(per_cfg.get("type")):
                    weights = np.array(per_cfg.get("weights", [1.0] * prev_units), dtype=np.float32).reshape(-1)
                    limit = min(prev_units, weights.shape[0])
                    per_kernel[:limit, col] = weights[:limit]
            if len(pl_current) > 0:
                new_weights = [per_kernel]
                if len(pl_current) > 1:
                    new_weights.append(np.array(pl_current[1], dtype=np.float32))
                pl_layer.set_weights(new_weights)

        # Transfer lower-level reference weights from higher output links.
        if lvl < len(levels) - 1:
            next_units = levels[lvl + 1]
            ref_kernel = np.zeros((next_units, units), dtype=np.float32)
            for col in range(units):
                ref_cfg = _legacy_func_cfg(legacy_config, lvl, col, "refcoll")
                if _is_weighted_sum_type(ref_cfg.get("type")):
                    weights = np.array(ref_cfg.get("weights", [1.0] * next_units), dtype=np.float32).reshape(-1)
                    limit = min(next_units, weights.shape[0])
                    ref_kernel[:limit, col] = weights[:limit]
            rl_layer = individual.model.get_layer(f"RL{lvl:02d}")
            rl_current = rl_layer.get_weights()
            if len(rl_current) > 0:
                new_weights = [ref_kernel]
                if len(rl_current) > 1:
                    new_weights.append(np.array(rl_current[1], dtype=np.float32))
                rl_layer.set_weights(new_weights)

        # Transfer top-level reference values where the architecture has a bias.
        # For the normal ElementWise top-level reference layer, reference values
        # live in individual.reference_values and are supplied through the model's
        # ReferencesInput during execution.
        if lvl == len(levels) - 1:
            rl_layer = individual.model.get_layer(f"RL{lvl:02d}")
            rl_current = rl_layer.get_weights()
            if len(rl_current) >= 2:
                bias = np.array(rl_current[1], dtype=np.float32)
                for col in range(units):
                    ref_cfg = _legacy_func_cfg(legacy_config, lvl, col, "refcoll")
                    if ref_cfg.get("type") in ("Variable", "EAVariable", "Constant", "EAConstant") and ref_cfg.get("value") is not None:
                        bias[col] = float(ref_cfg["value"])
                rl_layer.set_weights([rl_current[0], bias])

        # Transfer output gains/weights to OL## ElementWiseMultiplyLayer weights.
        try:
            ol_layer = individual.model.get_layer(f"OL{lvl:02d}")
            ol_current = ol_layer.get_weights()
            if len(ol_current) > 0:
                gain_weights = np.ones(units, dtype=np.float32)
                for col in range(units):
                    out_cfg = _legacy_func_cfg(legacy_config, lvl, col, "outcoll")
                    gain_weights[col] = _legacy_output_weight(out_cfg)
                ol_layer.set_weights([gain_weights])
        except ValueError:
            pass

    # T154: Transfer post-action weights to Actions layer.
    # Try both "Actions_final" (older builds) and "Actions" (current builds).
    post = legacy_config.get("post", {})
    if post:
        actions_layer = None
        for candidate in ("Actions_final", "Actions"):
            try:
                actions_layer = individual.model.get_layer(candidate)
                break
            except ValueError:
                pass

        if actions_layer is not None:
            actions_current = actions_layer.get_weights()
            if len(actions_current) > 0:
                kernel_shape = actions_current[0].shape  # (num_OL_units, num_actions)
                pw = np.zeros(kernel_shape, dtype=np.float32)
                num_ol_units = kernel_shape[0]
                import re as _re
                for action_idx, pk in enumerate(sorted(post)):
                    pv = post[pk]
                    if not _is_weighted_sum_type(pv.get("type", "")):
                        continue
                    weights_list = pv.get("weights")
                    links = pv.get("links", {})
                    if weights_list is None:
                        continue
                    for link_idx, link_key in enumerate(sorted(links, key=lambda k: int(k))):
                        link_name = links[link_key]
                        m = _re.search(r'C(\d+)', link_name)
                        if m:
                            ol_col = int(m.group(1))
                        else:
                            ol_col = link_idx
                        if ol_col < num_ol_units and link_idx < len(weights_list):
                            pw[ol_col, action_idx] = float(weights_list[link_idx])
                new_weights = [pw]
                if len(actions_current) > 1:
                    new_weights.append(actions_current[1])
                actions_layer.set_weights(new_weights)

    # Transfer per-action sigmoid range/slope from legacy EASigmoidWeightedSum
    if activation_funcs.get("actions") == "sigmoid":
        try:
            sigmoid_layer = individual.model.get_layer("Actions_sigmoid")
        except ValueError:
            sigmoid_layer = None
        if sigmoid_layer is not None:
            num_actions = len(sorted(post))
            range_vals = np.full(num_actions, 2.0, dtype=np.float32)
            slope_vals = np.full(num_actions, 10.0, dtype=np.float32)
            for action_idx, pk in enumerate(sorted(post)):
                pv = post[pk]
                if "Sigmoid" in (pv.get("type", "") or ""):
                    if pv.get("range") is not None:
                        range_vals[action_idx] = float(pv["range"])
                    if pv.get("slope") is not None:
                        slope_vals[action_idx] = float(pv["slope"])
            sigmoid_layer.set_weights([range_vals, slope_vals])

    # Apply explicit references override (e.g. from .properties file) to the
    # executable reference input values.  Do not warn for ElementWise top-level
    # reference layers: they intentionally multiply the ReferencesInput values.
    if "references" in legacy_config:
        refs = np.array(legacy_config["references"], dtype=np.float32)
        if refs.shape[0] != levels[-1]:
            raise ValueError(
                f"references length ({refs.shape[0]}) must match top-level units ({levels[-1]})"
            )
        individual.reference_values = refs

    individual._store_weights()
    return individual


# %% ../nbs/02_individual_utils.ipynb #a868c5ea
def _from_legacy_config_impl(cls, legacy_config: Dict[str, Any]) -> "DHPCTIndividual":
    """Create individual from exact PCTHierarchy config or old flat DPCT legacy format."""
    if _looks_like_pct_hierarchy_config(legacy_config):
        return _from_pct_legacy_config_impl(cls, legacy_config)

    if "env_name" not in legacy_config or "levels" not in legacy_config:
        raise ValueError("Unsupported legacy configuration format")

    converted = {
        "env_name": legacy_config["env_name"],
        "hierarchy": {
            "levels": legacy_config["levels"],
            "activation_funcs": legacy_config.get("activation_funcs", "linear"),
            "weight_types": legacy_config.get("weight_types", "float"),
            "obs_connection_level": legacy_config.get("obs_connection_level", 0),
        },
        "weights": legacy_config.get("weights", {}),
        "biases": legacy_config.get("biases", {}),
        "fixed_weights": legacy_config.get("fixed_weights", []),
        "fixed_levels": legacy_config.get("fixed_levels", []),
        "metadata": {
            "fitness": legacy_config.get("fitness", None),
            "random_seed": legacy_config.get("random_seed", None),
        },
    }

    if "toplevel_inputs_indexes" in legacy_config:
        converted["hierarchy"]["top_level_obs_indices"] = legacy_config["toplevel_inputs_indexes"]

    if "zerolevel_inputs_indexes" in legacy_config:
        converted["hierarchy"]["zerolevel_inputs_indexes"] = legacy_config["zerolevel_inputs_indexes"]

    if "references" in legacy_config:
        converted["hierarchy"]["reference_values"] = legacy_config["references"]

    return cls.from_config(converted)

