import ast as _ast
import re as _re_mod


def _parse_properties_file(filepath: str) -> Dict[str, Any]:
    """Parse a legacy PCT .properties file.

    Extracts the ``config = {...}`` Python dict literal and any scalar
    key-value properties (e.g. ``toplevel_inputs_indexes``, ``references``).
    """
    text = Path(filepath).read_text(encoding="utf-8")

    # Extract the config dict literal
    m = _re_mod.search(r'^config\s*=\s*', text, _re_mod.MULTILINE)
    if m is None:
        raise ValueError(f"No 'config = ...' line found in {filepath}")
    config_str = text[m.end():]
    # The dict may span one (very long) line; take until end of line
    config_line_end = config_str.find('\n')
    if config_line_end != -1:
        config_str = config_str[:config_line_end]
    config = _ast.literal_eval(config_str.strip())

    # Extract simple properties
    props: Dict[str, Any] = {"config": config}
    for key in ("toplevel_inputs_indexes", "zerolevel_inputs_indexes", "references"):
        pm = _re_mod.search(rf'^{key}\s*=\s*(.+)$', text, _re_mod.MULTILINE)
        if pm:
            raw = pm.group(1).strip()
            if raw.lower() == "none":
                continue
            props[key] = _ast.literal_eval(raw)

    return props


def _load_from_legacy_config_impl(cls, filepath: str) -> "DHPCTIndividual":
    """Load a legacy .properties config file and create an individual from it."""
    data = _parse_properties_file(filepath)
    config = data["config"]

    if "toplevel_inputs_indexes" in data:
        config["toplevel_inputs_indexes"] = data["toplevel_inputs_indexes"]

    if "zerolevel_inputs_indexes" in data:
        config["zerolevel_inputs_indexes"] = data["zerolevel_inputs_indexes"]

    if "references" in data:
        config["references"] = data["references"]

    return _from_legacy_config_impl(cls, config)
